Would be something like this in the invoker:

```
function invoke(address sponsee, uint256 nextra, address to, uint256 mingas, uint256 value, bytes calldata, uint8 v, bytes32 r, bytes32 s) {
    bytes memory arguments = abi.encode(sponsee, nextra, to, mingas, value, calldata, v, r, s);
    call_precompile(arguments);
}
```

Then in the precompile, you'd do something like:

```
DOMAIN_SEPARATOR = keccak256(abi.encode(
    keccak256("EIP712Domain(uint256 chainId,address verifyingContract)"),
    chainid(),
    address(invoker)
));

TYPEHASH = keccak256("Eip3074(address sponsee,uint256 nextra,address to,uint256 mingas,uint256 value,bytes calldata");

bytes32 digest =
    keccak256(abi.encodePacked(
        "\x19\x01",
        DOMAIN_SEPARATOR,
        keccak256(abi.encode(TYPEHASH,
                             sponsee,
                             nextra,
                             to,
                             mingas,
                             value,
                             calldata))
));

require(sponsee == ecrecover(digest, v, r, s));
call_set_sender{value: ...}(calldata...);
```

